package com.gathin.tvhome;
import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;
public class UpdatePolicyTest {
 @Test public void acceptsOnlyTheOwnedRepositoryApks(){assertTrue(UpdatePolicy.artifact("https://github.com/einfall/lumadock/releases/download/v1.0.0/Luma-Dock-1.0.0-universal.apk"));for(String u:new String[]{"https://github.com/other/lumadock/releases/download/v1.0.0/a.apk","https://github.com/einfall/lumadock/raw/main/a.apk","https://evil.test/a.apk","http://github.com/einfall/lumadock/releases/download/v1/a.apk","https://github.com/einfall/lumadock/releases/download/v1/../a.apk","https://user@github.com/einfall/lumadock/releases/download/v1/a.apk","https://github.com:444/einfall/lumadock/releases/download/v1/a.apk"})assertFalse(u,UpdatePolicy.artifact(u));}
 @Test public void redirectsAllowOnlyTheKnownHttpsGitHubOrigins(){for(String h:new String[]{"github.com","release-assets.githubusercontent.com","objects.githubusercontent.com","github-releases.githubusercontent.com"})assertTrue(UpdatePolicy.transport("https://"+h+"/download"));for(String u:new String[]{"https://github.com.evil.test/a","file:///tmp/a.apk","https://github.com@evil.test/a","https://objects.githubusercontent.com.evil.test/a","http://release-assets.githubusercontent.com/a",null,""})assertFalse(UpdatePolicy.transport(u));}
 @Test public void checksumsMustBeFullSha256(){assertTrue(UpdatePolicy.hash("a".repeat(64)));assertTrue(UpdatePolicy.hash("F".repeat(64)));for(String h:new String[]{null,"","a".repeat(63),"a".repeat(65),"z".repeat(64)})assertFalse(UpdatePolicy.hash(h));}
 @Test public void updatesMustMatchPackageSdkAndNondecreasingVersion(){assertTrue(UpdatePolicy.compatible("com.app","com.app",30,26,100,101));assertTrue(UpdatePolicy.compatible("com.app","com.app",30,26,100,100));assertFalse(UpdatePolicy.compatible("com.app","other",30,26,100,101));assertFalse(UpdatePolicy.compatible("com.app","com.app",30,31,100,101));assertFalse(UpdatePolicy.compatible("com.app","com.app",30,25,100,101));assertFalse(UpdatePolicy.compatible("com.app","com.app",30,26,100,99));assertFalse(UpdatePolicy.compatible("com.app","com.app",30,26,0,0));}
 @Test public void dailyChecksRecoverFromClockChangesAndDoNotPollEveryResume(){assertTrue(UpdatePolicy.due(5000,0));assertFalse(UpdatePolicy.due(6000,5000));assertFalse(UpdatePolicy.due(5000+UpdatePolicy.CHECK_MS-1,5000));assertTrue(UpdatePolicy.due(5000+UpdatePolicy.CHECK_MS,5000));assertTrue(UpdatePolicy.due(4000,5000));}
 @Test public void allCurrentSigningCertificatesMustMatch(){assertTrue(UpdatePolicy.sameSigners(Set.of("a"),Set.of("a")));assertTrue(UpdatePolicy.sameSigners(Set.of("a","b"),Set.of("b","a")));assertFalse(UpdatePolicy.sameSigners(Set.of("a"),Set.of("b")));assertFalse(UpdatePolicy.sameSigners(Set.of("a","b"),Set.of("a")));assertFalse(UpdatePolicy.sameSigners(Set.of(),Set.of()));assertFalse(UpdatePolicy.sameSigners(null,Set.of("a")));}
}
